CREATE TYPE "AssessmentAssignmentStatus" AS ENUM ('ASSIGNED','IN_PROGRESS','COMPLETED','EXPIRED','CANCELLED');CREATE TYPE "ShortlistStatus" AS ENUM ('DRAFT','PUBLISHED','CLOSED');
CREATE TABLE "assessment_types"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"tenant_id" BIGINT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,FOREIGN KEY("tenant_id") REFERENCES "tenants"("id") ON DELETE RESTRICT);CREATE UNIQUE INDEX "assessment_types_tenant_id_name_key" ON "assessment_types"("tenant_id","name");
CREATE TABLE "assessment_versions"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"assessment_type_id" BIGINT NOT NULL,"version" INTEGER NOT NULL,"definition" JSONB NOT NULL,"interpretation_ranges" JSONB NOT NULL,"authorized_use_confirmed" BOOLEAN NOT NULL DEFAULT false,"published_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("assessment_type_id") REFERENCES "assessment_types"("id") ON DELETE RESTRICT);CREATE UNIQUE INDEX "assessment_versions_assessment_type_id_version_key" ON "assessment_versions"("assessment_type_id","version");
CREATE TABLE "assessment_assignments"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"assessment_version_id" BIGINT NOT NULL,"candidate_id" BIGINT NOT NULL,"status" "AssessmentAssignmentStatus" NOT NULL DEFAULT 'ASSIGNED',"max_attempts" INTEGER NOT NULL DEFAULT 1,"attempts_used" INTEGER NOT NULL DEFAULT 0,"started_at" TIMESTAMPTZ(6),"completed_at" TIMESTAMPTZ(6),"expires_at" TIMESTAMPTZ(6),"responses" JSONB,FOREIGN KEY("assessment_version_id") REFERENCES "assessment_versions"("id") ON DELETE RESTRICT,FOREIGN KEY("candidate_id") REFERENCES "candidates"("id") ON DELETE RESTRICT);CREATE INDEX "assessment_assignments_candidate_id_status_idx" ON "assessment_assignments"("candidate_id","status");
CREATE TABLE "assessment_results"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"assignment_id" BIGINT NOT NULL UNIQUE,"raw_score" DECIMAL(12,4) NOT NULL,"factor_scores" JSONB NOT NULL,"interpretation" TEXT,"professional_report" TEXT,"client_visible" BOOLEAN NOT NULL DEFAULT false,"interpreted_by_id" BIGINT,"calculated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("assignment_id") REFERENCES "assessment_assignments"("id") ON DELETE RESTRICT,FOREIGN KEY("interpreted_by_id") REFERENCES "users"("id") ON DELETE RESTRICT);
CREATE TABLE "scoring_matrices"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"tenant_id" BIGINT NOT NULL,"name" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,FOREIGN KEY("tenant_id") REFERENCES "tenants"("id") ON DELETE RESTRICT);CREATE UNIQUE INDEX "scoring_matrices_tenant_id_name_key" ON "scoring_matrices"("tenant_id","name");
CREATE TABLE "scoring_matrix_versions"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"matrix_id" BIGINT NOT NULL,"version" INTEGER NOT NULL,"published_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("matrix_id") REFERENCES "scoring_matrices"("id") ON DELETE RESTRICT);CREATE UNIQUE INDEX "scoring_matrix_versions_matrix_id_version_key" ON "scoring_matrix_versions"("matrix_id","version");
CREATE TABLE "scoring_variables"("id" BIGSERIAL PRIMARY KEY,"version_id" BIGINT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"weight" DECIMAL(7,4) NOT NULL,"minimum" DECIMAL(12,4) NOT NULL,"maximum" DECIMAL(12,4) NOT NULL,"required" BOOLEAN NOT NULL DEFAULT false,FOREIGN KEY("version_id") REFERENCES "scoring_matrix_versions"("id") ON DELETE CASCADE);CREATE UNIQUE INDEX "scoring_variables_version_id_code_key" ON "scoring_variables"("version_id","code");
CREATE TABLE "scoring_rules"("id" BIGSERIAL PRIMARY KEY,"version_id" BIGINT NOT NULL,"code" TEXT NOT NULL,"description" TEXT NOT NULL,"condition" JSONB NOT NULL,"effect" JSONB NOT NULL,FOREIGN KEY("version_id") REFERENCES "scoring_matrix_versions"("id") ON DELETE CASCADE);CREATE UNIQUE INDEX "scoring_rules_version_id_code_key" ON "scoring_rules"("version_id","code");
ALTER TABLE "vacancies" ADD COLUMN "scoring_version_id" BIGINT;ALTER TABLE "vacancies" ADD CONSTRAINT "vacancies_scoring_version_id_fkey" FOREIGN KEY("scoring_version_id") REFERENCES "scoring_matrix_versions"("id") ON DELETE RESTRICT;
CREATE TABLE "score_runs"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"application_id" BIGINT NOT NULL,"version_id" BIGINT NOT NULL,"inputs" JSONB NOT NULL,"total" DECIMAL(12,4) NOT NULL,"excluded" BOOLEAN NOT NULL DEFAULT false,"explanation" JSONB NOT NULL,"calculated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("application_id") REFERENCES "applications"("id") ON DELETE RESTRICT,FOREIGN KEY("version_id") REFERENCES "scoring_matrix_versions"("id") ON DELETE RESTRICT);CREATE INDEX "score_runs_application_id_calculated_at_idx" ON "score_runs"("application_id","calculated_at");CREATE INDEX "score_runs_version_id_total_idx" ON "score_runs"("version_id","total");
CREATE TABLE "score_components"("id" BIGSERIAL PRIMARY KEY,"score_run_id" BIGINT NOT NULL,"variable_code" TEXT NOT NULL,"raw_value" DECIMAL(12,4) NOT NULL,"normalized_value" DECIMAL(12,4) NOT NULL,"weighted_value" DECIMAL(12,4) NOT NULL,FOREIGN KEY("score_run_id") REFERENCES "score_runs"("id") ON DELETE CASCADE);CREATE INDEX "score_components_score_run_id_idx" ON "score_components"("score_run_id");
CREATE TABLE "shortlists"("id" BIGSERIAL PRIMARY KEY,"public_id" UUID NOT NULL UNIQUE,"vacancy_id" BIGINT NOT NULL,"status" "ShortlistStatus" NOT NULL DEFAULT 'DRAFT',"target_size" INTEGER NOT NULL DEFAULT 3,"presented_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("vacancy_id") REFERENCES "vacancies"("id") ON DELETE RESTRICT);CREATE INDEX "shortlists_vacancy_id_status_idx" ON "shortlists"("vacancy_id","status");
CREATE TABLE "shortlist_entries"("shortlist_id" BIGINT NOT NULL,"application_id" BIGINT NOT NULL,"position" INTEGER NOT NULL,"inclusion_reason" TEXT NOT NULL,"manually_selected" BOOLEAN NOT NULL DEFAULT false,PRIMARY KEY("shortlist_id","application_id"),FOREIGN KEY("shortlist_id") REFERENCES "shortlists"("id") ON DELETE CASCADE,FOREIGN KEY("application_id") REFERENCES "applications"("id") ON DELETE RESTRICT);CREATE UNIQUE INDEX "shortlist_entries_shortlist_id_position_key" ON "shortlist_entries"("shortlist_id","position");
